// Decision D5-2 (round 5, contract C6): the engine leaves out of the target set
// no source file because of what it looks like or where it is. These tests drive
// inScopeTargets over trees that carry every signal round 4 trusted.

func minified() string { return "!function(){" + strings.Repeat("a=b(c,d);", 300) + "}();\n" }

// Every source file under the cap is a target, whatever its name, directory,
// banner, header, literals or markers say (C4B-02, C4B-03, review items 1, 2, 7
// and 8), and nothing is declared out of scope.
func TestEverySourceFileUnderTheCapIsATarget(t *testing.T) {
	root := t.TempDir()
	files := map[string]string{
		"routes.min.js":                   spikeApp,
		"vendor/app/routes.js":            spikeApp,
		"dist/api.js":                     spikeApp,
		"build/api.js":                    spikeApp,
		"target/api.js":                   spikeApp,
		"node_modules/x.js":               spikeApp,
		"node_modules/.package-lock.json": `{"lockfileVersion": 3}`,
		"node_modules/dep/index.js":       spikeApp,
		".venv/app.py":                    picklePy,
		"venv/pyvenv.cfg":                 "home = /usr/bin\n",
		"venv/lib/site-packages/a-1.0.dist-info/RECORD":   "x",
		"venv/lib/site-packages/a-1.0.dist-info/METADATA": "x",
		"venv/lib/app.py":          picklePy,
		"conda/conda-meta/history": "",
		"conda/app.py":             picklePy,
		"static/bundle.js":         minified(),
		"public/app.min.js":        minified(),
		"lib/jquery.js":            vendoredJQuery(),
		"banner/socketio.js":       "/*! Socket.IO v4.7.2 | (c) 2014 */\n// socket socket socket\n" + spikeApp + strings.Repeat("function p(a) { return a; }\n", 400),
		"banner/lodash.js":         "/** @license Lodash <https://lodash.com/> */\n// lodash lodash lodash\n" + spikeApp + strings.Repeat("function p(a) { return a; }\n", 400),
		"banner/react.js":          "/** React v18.2.0 | MIT */\n// react react react\n" + spikeApp + strings.Repeat("function p(a) { return a; }\n", 400),
		"gen/handler.go":           "// Code generated by acme-gen v1.0. DO NOT EDIT.\npackage x\n",
		"gen/handler.py":           "# @generated\n" + picklePy,
		"api/routes.js":            "const COUNTRIES = [" + strings.Repeat(`{"code":"C","name":"N","region":{"id":0},"vat":3},`, 700) + "];\n" + spikeApp,
		"compiled/main.js":         "/******/ (() => { // webpackBootstrap\n" + spikeApp + "\n//# sourceMappingURL=main.js.map\n",
		"sub/.git/app.py":          picklePy,
		"sub/.git/HEAD":            "ref: refs/heads/main\n",
		"sub/.git/objects/x.py":    picklePy,
		"sub/.git/refs/heads/y.py": picklePy,
		"a/objects/b.py":           picklePy,
	}
	writeTree(t, root, files)
	targets := inScopeTargets(root, nil)
	if len(targets.Excludes) != 0 || targets.Coverage.Declared() {
		t.Fatalf("excluded %q / declared %q; nothing under the cap is left out", targets.Excludes, targets.Coverage.DeclaredDetail(1<<20))
	}
	got := " " + strings.Join(targets.files, " ") + " "
	for rel := range files {
		if languageOf(rel) == "" {
			continue
		}
		if !strings.Contains(got, " "+rel+" ") {
			t.Errorf("%s is not a target", rel)
		}
	}
}

// An over-cap source file is lost evaluation whatever its header, content or
// name says; nothing is declared out of scope on evidence.
func TestOverCapSourceFilesAreAlwaysLostEvaluation(t *testing.T) {
	root := t.TempDir()
	huge := func(prefix string) string { return prefix + strings.Repeat("a", scope.MaxFileBytes) + "\n" }
	writeTree(t, root, map[string]string{
		"api/user.pb.go":        "// Code generated by protoc-gen-go. DO NOT EDIT.\n" + huge("package api\n// "),
		"web/bundle.js":         strings.Repeat("!function(){"+strings.Repeat("a=b(c,d);", 300)+"}();\n", 400),
		"src/big.js":            huge("// "),
		"package-lock.json":     "{}", // not a Semgrep target at all
		"web/gen/data.py":       huge("# "),
		"web/gen/gen_data.py":   "# This file is automatically generated. Do not edit.\n" + huge("# "),
		"web/gen/fake-lock.js":  huge("// package-lock.json\n// "),
		"web/gen/yarn.lock.min": "x",
	})
	targets := inScopeTargets(root, nil)
	lost := strings.Join(targets.Coverage.Limitations("semgrep"), "\n")
	if n := targets.Coverage.LostFiles(); n != 6 {
		t.Errorf("LostFiles = %d (%s); want the six over-cap source files", n, targets.Coverage.LostDetail(1<<20))
	}
	for _, f := range []string{"api/user.pb.go", "web/bundle.js", "src/big.js", "web/gen/data.py", "web/gen/gen_data.py", "web/gen/fake-lock.js"} {
		if !strings.Contains(lost, f) {
			t.Errorf("%s is not listed lost: %q", f, lost)
		}
	}
	if targets.Coverage.Declared() || len(targets.Excludes) != 0 {
		t.Errorf("declared %q, excludes %q; an over-cap file is a gap, not an exclusion", targets.Coverage.DeclaredDetail(1<<20), targets.Excludes)
	}
}

// Only <root>/.git with a real layout is left out, quietly, and Semgrep is told
// to skip exactly it; a .git with a forged layout, or one anywhere else, is
// ordinary content.
func TestOnlyTheRealRootGitDirectoryIsLeftOut(t *testing.T) {
	real := t.TempDir()
	writeTree(t, real, map[string]string{
		".git/HEAD": "ref: refs/heads/main\n", ".git/objects/x": "x", ".git/refs/heads/main": "x",
		".git/hooks/pre-commit.py": picklePy, "app.py": picklePy,
	})
	targets := inScopeTargets(real, nil)
	if got := strings.Join(targets.files, " "); got != "app.py" {
		t.Errorf("targets = %q; want only app.py", got)
	}
	if got := strings.Join(targets.Excludes, " "); got != "/.git" || targets.Coverage.Declared() {
		t.Errorf("Excludes = %q, declared %q; the VCS directory is skipped quietly", got, targets.Coverage.DeclaredDetail(240))
	}
	fake := t.TempDir()
	writeTree(t, fake, map[string]string{".git/HEAD": "x", ".git/app.py": picklePy, "app.py": picklePy})
	targets = inScopeTargets(fake, nil)
	if got := strings.Join(targets.files, " "); got != ".git/app.py app.py" || len(targets.Excludes) != 0 {
		t.Errorf("a .git with no objects/ and refs/: targets %q, excludes %q; it is ordinary content", got, targets.Excludes)
	}
}

// A diff scan holds to the same rule: a changed file under node_modules or a
// virtualenv-shaped tree is a target, a changed file under the real root .git is
// not.
func TestDiffScanEvaluatesAChangedFileUnderAnInstalledTree(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root, map[string]string{
		"node_modules/.package-lock.json": `{"lockfileVersion": 3}`,
		"node_modules/lib/i.js":           spikeApp,
		"node_modules/lib/j.js":           spikeApp,
		"venv/pyvenv.cfg":                 "home = /usr/bin\n",
		"venv/lib/k.py":                   picklePy,
		"vendor/app.js":                   spikeApp,
		"src/a.js":                        spikeApp,
		".git/HEAD":                       "ref: refs/heads/main\n",
		".git/objects/x":                  "x",
		".git/refs/heads/m":               "x",
		".git/hooks/h.py":                 picklePy,
	})
	allow := gitdiff.NewAllowlist(root, []string{"node_modules/lib/i.js", "node_modules/lib/j.js", "venv/lib/k.py", "vendor/app.js", "src/a.js", ".git/hooks/h.py"})
	targets := inScopeTargets(root, allow)
	if got := strings.Join(targets.files, " "); got != "node_modules/lib/i.js node_modules/lib/j.js src/a.js vendor/app.js venv/lib/k.py" {
		t.Errorf("targets = %q", got)
	}
	if targets.Coverage.Declared() {
		t.Errorf("declared %q", targets.Coverage.DeclaredDetail(240))
	}
}

// A file that cannot be opened is lost evaluation, named; a FIFO or a link with
// a source name is never opened, so it cannot block the run.
func TestAnUnreadableOrSpecialSourceFileNeverBlocksOrHides(t *testing.T) {
	if os.Geteuid() == 0 {
		t.Skip("root reads every file")
	}
	root := t.TempDir()
	writeTree(t, root, map[string]string{"ok.py": picklePy, "locked.py": picklePy})
	if err := os.Chmod(filepath.Join(root, "locked.py"), 0); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.Chmod(filepath.Join(root, "locked.py"), 0o644) })
	targets := inScopeTargets(root, nil)
	if got := targets.Coverage.LostDetail(240); got != "lost evaluation: 1 in-scope file not read: 1 unreadable (locked.py)" {
		t.Errorf("lost = %q", got)
	}
	if got := strings.Join(targets.files, " "); got != "ok.py" {
		t.Errorf("targets = %q", got)
	}
}

// excludePattern: a pattern that names exactly one path, escaped; a path that
// cannot be written safely is not excluded and stays in scope.
func TestExcludePatternsAreAnchoredAndEscaped(t *testing.T) {
	for _, tc := range []struct {
		rel  string
		want string
		ok   bool
	}{
		{"vendor", "/vendor", true},
		{"web/lib/jquery.js", "/web/lib/jquery.js", true},
		{"a b/c.js", "/a b/c.js", true},
		{"br[x]/w.js", `/br\[x\]/w.js`, true},
		{"a*b?.js", `/a\*b\?.js`, true},
		{"back\\slash.js", `/back\\slash.js`, true},
		{"!bang.js", "/!bang.js", true},
		{"#hash.js", "/#hash.js", true},
		{"héllo/ü.js", "/héllo/ü.js", true},
		{"line\nbreak.js", "", false},
		{"nul\x00.js", "", false},
		{" lead.js", "", false},
		{"trail.js ", "", false},
		{"bad\xffutf.js", "", false},
		{"", "", false},
	} {
		got, ok := excludePattern(tc.rel)
		if got != tc.want || ok != tc.ok {
			t.Errorf("excludePattern(%q) = %q, %v; want %q, %v", tc.rel, got, ok, tc.want, tc.ok)
		}
	}
}

func TestDiffScanListsAChangedFileReachedThroughALink(t *testing.T) {
	root := t.TempDir()
	outside := t.TempDir()
	writeTree(t, outside, map[string]string{"x.js": spikeApp})
	writeTree(t, root, map[string]string{"src/a.js": spikeApp})
	if err := os.Symlink(outside, filepath.Join(root, "linked")); err != nil {
		t.Skip("no symlinks here")
	}
	allow := gitdiff.NewAllowlist(root, []string{"linked/x.js", "src/a.js"})
	targets := inScopeTargets(root, allow)
	if got := targets.Coverage.Names(scope.ReasonSymlink); len(got) != 1 || got[0] != "linked/x.js" {
		t.Errorf("symlink names = %q; want linked/x.js", got)
	}
	if got := strings.Join(targets.files, " "); got != "src/a.js" {
		t.Errorf("targets = %q", got)
	}
}

// sre3-06 (Semgrep's half): a symbolic link to source, or to a directory, is
// listed as not followed, never silently skipped.
func TestSymlinksAreListedNotFollowed(t *testing.T) {
	root := t.TempDir()
	outside := t.TempDir()
	writeTree(t, outside, map[string]string{"real.py": picklePy, "dir/x.js": spikeApp})
	writeTree(t, root, map[string]string{"app.py": picklePy, "notes.txt": "x"})
	for name, target := range map[string]string{"helper.py": filepath.Join(outside, "real.py"), "shared": filepath.Join(outside, "dir"), "readme-link.txt": filepath.Join(root, "notes.txt")} {
		if err := os.Symlink(target, filepath.Join(root, name)); err != nil {
			t.Skip("no symlinks here")
		}
	}
	targets := inScopeTargets(root, nil)
	got := targets.Coverage.Names(scope.ReasonSymlink)
	if strings.Join(got, " ") != "helper.py shared/" {
		t.Errorf("symlinks = %q; want helper.py and shared/ (a link to a text file is not source)", got)
	}
	if targets.Coverage.Lost() {
		t.Errorf("a link is declared, not lost: %s", targets.Coverage.LostDetail(240))
	}
}

// redteam3-semgrep-02, redteam4-d6-02, DE4-04: a source file Semgrep does not
// select by its extension (another case, or .cts/.mts/.es6/.vue) is in scope,
// never declared out of scope by its name. It is handed to Semgrep by name (the
// extensions pass); a file the pass does not report is lost evaluation.
func TestFilesSemgrepDoesNotSelectAreInScopeAndGoToTheExtensionsPass(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root, map[string]string{"APP.JS": spikeApp, "Server.Py": picklePy, "x.cts": spikeApp, "ui.vue": "<template/>", "a.js": spikeApp, "notes.TXT": "x"})
	targets := inScopeTargets(root, nil)
	if got := strings.Join(targets.files, " "); got != "APP.JS Server.Py a.js ui.vue x.cts" {
		t.Errorf("targets = %q; want every source file, whatever the case of its extension", got)
	}
	if got := strings.Join(targets.explicit, " "); got != "APP.JS Server.Py ui.vue x.cts" {
		t.Errorf("explicit = %q; want the files Semgrep does not select itself", got)
	}
	if targets.Coverage.Declared() {
		t.Errorf("a file name must not declare source out of scope: %s", targets.Coverage.DeclaredDetail(240))
	}
	if languageOf("APP.JS") != "javascript" || languageOf("app.js") != "javascript" || languageOf("a.PYI") != "python" || languageOf("n.TXT") != "" {
		t.Error("languageOf must match the extension without regard to case")
	}
	if semgrepSelects("APP.JS") || !semgrepSelects("app.js") {
		t.Error("semgrepSelects must match the extension exactly, as Semgrep does")
	}
	// Unreported by Semgrep, they are lost evaluation, named.
	targets.checkScanned(map[string]bool{"a.js": true}, true)
	if got := targets.Coverage.LostDetail(240); !strings.Contains(got, "APP.JS") || !strings.Contains(got, "Server.Py") {
		t.Errorf("lost = %q; want the unreported upper-case files named", got)
	}
}

// qa3-02: an unreadable directory under the walk is listed unreadable.
func TestAnUnreadableDirectoryIsListed(t *testing.T) {
	if os.Geteuid() == 0 {
		t.Skip("root reads every directory")
	}
	root := t.TempDir()
	writeTree(t, root, map[string]string{"ok/a.js": spikeApp, "secret/b.js": spikeApp})
	if err := os.Chmod(filepath.Join(root, "secret"), 0); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.Chmod(filepath.Join(root, "secret"), 0o755) })
	targets := inScopeTargets(root, nil)
	if got := targets.Coverage.LostDetail(240); got != "lost evaluation: 1 in-scope file not read: 1 unreadable (secret/)" {
		t.Errorf("lost = %q", got)
	}
}

// qa3-02: every spelling of a rule error is a rule error, so a pack that did
// not load is never read as a pack that found nothing.
func TestEveryRuleErrorSpellingIsARuleError(t *testing.T) {
	for typ := range ruleErrorTypes {
		doc := `{"results":[],"errors":[{"level":"error","type":"` + typ + `","message":"bad rule","path":"/x/r.yaml"}],"time":{"fixpoint_timeouts":[]}}`
		run := parseRun([]byte(doc), t.TempDir())
		if len(run.RuleErrors) != 1 || run.RuleErrors[0].Type != typ {
			t.Errorf("%q: RuleErrors = %+v", typ, run.RuleErrors)
		}
	}
	for _, typ := range []string{"Rule parse error", "Invalid YAML", "Pattern parse error", "Incompatible rule", "InvalidRuleSchemaError", "RuleParseError", "PatternParseError", "UnknownLanguageError", "InvalidYaml", "IncompatibleRule"} {
		if !ruleErrorTypes[typ] {
			t.Errorf("%q is not a rule error type", typ)
		}
	}
}
